window.LANTERN_VIDEOS = [{"id":"pepper-and-carrot-potion-contest","type":"video","title":"Pepper & Carrot: The Potion Contest","creator":"Morevna Project","year":2017,"level":"A2","category":"fun","durationSeconds":454,"genre":"comedy","summaryTr":"Genç cadı Pepper ve turuncu kedisi Carrot, kasabanın büyük iksir yarışmasına katılır. Rakipler göz kamaştırıcı iksirler sunarken Pepper'ın elindeki şişe herkesi şaşırtacaktır. David Revoy'un çizgi romanından uyarlanmış neşeli bir animasyon.","levelNoteTr":"A2, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî bir CEFR derecesi değildir. Cümleler kısa ve günlük; iksir, büyü ve sunucu konuşmalarındaki süslü sözcükler kelime desteği gerektirebilir.","advisoryTr":"Çizgi film tarzı hafif aksiyon ve zararsız bir \"kedi çişi\" esprisi içerir; tüm yaşlara uygundur.","videoUrl":"https://peertube.touhoppai.moe/static/web-videos/79ff0983-3f55-4111-9f7d-f3d3feeefb69-720.mp4","qualities":[{"label":"360p","url":"https://peertube.touhoppai.moe/static/web-videos/79ff0983-3f55-4111-9f7d-f3d3feeefb69-360.mp4","sizeMB":30},{"label":"720p","url":"https://peertube.touhoppai.moe/static/web-videos/79ff0983-3f55-4111-9f7d-f3d3feeefb69-720.mp4","sizeMB":62},{"label":"1080p","url":"https://peertube.touhoppai.moe/static/web-videos/79ff0983-3f55-4111-9f7d-f3d3feeefb69-1080.mp4","sizeMB":102}],"source":{"name":"Morevna Project — Pepper & Carrot Motion Comic, Episode 6","url":"https://morevnaproject.org/pepper-and-carrot/episode-6","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","credit":"Morevna Project · Yönetmen ve animasyon: Nikolai Mamashev · David Revoy'un Pepper & Carrot çizgi romanına dayanır","watchUrl":"https://peertube.touhoppai.moe/videos/watch/79ff0983-3f55-4111-9f7d-f3d3feeefb69"},"subtitleSource":{"name":"Morevna Project — İngilizce SRT altyazısı","url":"https://raw.githubusercontent.com/morevnaproject/subtitles-translation/master/output/pepper-and-carrot-ep6/pepper-and-carrot-ep6-eng.srt","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","changeNoteTr":"Altyazı sözleri korunmuş; [yawns] gibi ses notları ve biçim etiketleri kaldırılıp zamanlar saniyeye dönüştürülmüştür."},"captions":[{"start":1.03,"end":3.53,"text":"Morevna Project..."},{"start":4.37,"end":6.78,"text":"...in association with \"Ethic Cinema\"..."},{"start":7.24,"end":8.51,"text":"...presents."},{"start":24.24,"end":28.24,"text":"Oh, I fell asleep with the window open again..."},{"start":29.96,"end":32.76,"text":"Ufff... it's so windy..."},{"start":33.62,"end":36.91,"text":"...and why can I see Komona through the window?"},{"start":37.24,"end":38.24,"text":"Komona?!"},{"start":39.2,"end":39.99,"text":"THE CONTEST!!!"},{"start":41.7,"end":43.28,"text":"In previous episodes:"},{"start":43.45,"end":45.49,"text":"Pepper spent a lot of effort..."},{"start":45.87,"end":49.49,"text":"...preparing for the potion contest."},{"start":50.04,"end":50.87,"text":"I must've..."},{"start":51.21,"end":54,"text":"...must've accidentally fallen asleep..."},{"start":54.47,"end":55.1,"text":"But..."},{"start":56.18,"end":57.32,"text":"But...where am I?"},{"start":58.22,"end":59.16,"text":"Oh!!!"},{"start":64.88,"end":68.58,"text":"Carrot! It's so cute that you took care of everything!"},{"start":69.64,"end":70.64,"text":"Meow!"},{"start":71.62,"end":76.04,"text":"You even thought to bring a potion, my clothes, and my hat!"},{"start":77.12,"end":80.67,"text":"Well, let's see which potion you brought."},{"start":81.17,"end":83.04,"text":"So, what do we have here?"},{"start":83.87,"end":85.87,"text":"Whaaaat?!"},{"start":88.74,"end":92.84,"text":"Caaaaaaarrrrrooooooot!!!!!!!"},{"start":93.64,"end":97.4,"text":"Pepper & Carrot. Episode 6: The Potion Contest"},{"start":98.33,"end":103.12,"text":"As Mayor of Komona, I declare the potion contest..."},{"start":103.42,"end":105.08,"text":"...open!"},{"start":106.87,"end":110.87,"text":"Four young witches are participating in this contest!"},{"start":111.92,"end":114.54,"text":"Please give a huge round of applause!"},{"start":120.62,"end":124.62,"text":"It is an honor to welcome the ravishing and ingenious witch..."},{"start":125.21,"end":127.67,"text":"...from the great Technologist's Union!!!.."},{"start":128.04,"end":131.78,"text":"Coriander!"},{"start":133.04,"end":137.71,"text":"And don't forget about our local girl, Komona's very own witch..."},{"start":138.08,"end":140.96,"text":"Saffron!"},{"start":146.66,"end":148.92,"text":"Our third participant..."},{"start":149.14,"end":152.58,"text":"...comes to us from the lands of the setting moons..."},{"start":153.04,"end":154.92,"text":"...the mysterious..."},{"start":155.9,"end":158.34,"text":"...Shichimi!"},{"start":160.12,"end":164.52,"text":"And finally our last participant, from the forest of Squirrel's End..."},{"start":164.82,"end":166.3,"text":"...Pepper."},{"start":169.34,"end":170.78,"text":"Ladies and gentlemen!"},{"start":170.87,"end":176.46,"text":"The winner of the grand prize will be determined by applaud-o-meter!"},{"start":176.58,"end":180.42,"text":"Let the games begin!"},{"start":182.58,"end":187.37,"text":"Well! First up Coriander's demonstration."},{"start":189.83,"end":191.5,"text":"Ladies & gentlemen..."},{"start":191.96,"end":195.04,"text":"...fear death no more, thanks to my..."},{"start":195.67,"end":197.37,"text":"...Potion of Zombification!"},{"start":207.98,"end":209.7,"text":"Amazing!"},{"start":210.56,"end":217.18,"text":"With this mi-ra-cu-lous potion, Coriander defies death itself!"},{"start":218.54,"end":220.62,"text":"Yes-yes-yes..."},{"start":221.46,"end":223.52,"text":"A potion of Zombification.."},{"start":223.92,"end":225.2,"text":"that's nothing!"},{"start":225.21,"end":227.33,"text":"It's time to rate MY potion."},{"start":227.83,"end":231.83,"text":"The real potion you've all been waiting for..."},{"start":236.48,"end":238.38,"text":"...The Potion of Poshness!"},{"start":241.12,"end":243.71,"text":"Fantastic!"},{"start":243.96,"end":245.75,"text":"Incredible!"},{"start":246.29,"end":250.8,"text":"This potion could make all of Komona rich!"},{"start":250.96,"end":253.58,"text":"It seems, Coriander has already been eliminated!"},{"start":253.87,"end":257.87,"text":"Will Shichimi be able to beat that last demonstration?"},{"start":258.83,"end":262.7,"text":"I... I did not know we had to give a demonstration."},{"start":263.04,"end":264.37,"text":"Come on Shichimi!"},{"start":264.42,"end":265.79,"text":"Everyone's waiting for you!"},{"start":266.33,"end":267.17,"text":"No!.."},{"start":267.58,"end":268.12,"text":"I cannot!.."},{"start":268.46,"end":270.2,"text":"It is too dangerous!.."},{"start":270.4,"end":271.64,"text":"S-sorry!.."},{"start":272.37,"end":273.75,"text":"Ladies and gentlemen..."},{"start":274,"end":275.5,"text":"...it seems that Shichimi forfeits..."},{"start":275.54,"end":276.42,"text":"Give me that!"},{"start":276.58,"end":277.37,"text":"CAREFUL!!!"},{"start":277.66,"end":279.48,"text":"What could be so dangerous?"},{"start":279.68,"end":283.46,"text":"You're just scared because your potion isn't as fantastic as mine!"},{"start":284.58,"end":286.9,"text":"No-no, it is a potion of..."},{"start":287.96,"end":290.84,"text":"...GIANT MONSTERS!!!"},{"start":298.1,"end":299.94,"text":"Mr. Mayor, Mr. Mayor!"},{"start":300.1,"end":301.26,"text":"Is it my turn now???"},{"start":301.28,"end":302.34,"text":"Run!"},{"start":307.52,"end":311.26,"text":"You're lucky, Carrot; It seems nobody will see your wondrous potion..."},{"start":311.5,"end":313.6,"text":"She will destroy our town!!!"},{"start":314.72,"end":317.76,"text":"Wait, I think I have an idea!"},{"start":326.06,"end":326.96,"text":"Hey!"},{"start":327.44,"end":330.06,"text":"You oversized-posh-zombie-canary!"},{"start":330.12,"end":332.37,"text":"Wanna try one last \"potion\"?"},{"start":333.42,"end":334.71,"text":"But first..."},{"start":334.79,"end":337,"text":"...read the label!"},{"start":337.92,"end":339.48,"text":"Read it carefully!"},{"start":344.36,"end":349.92,"text":"If you don't get out of Komona right away, trust me: I'll pour it all over you!"},{"start":350.58,"end":351.25,"text":"Understood?!"},{"start":375.71,"end":380.74,"text":"Because she saved our town we award first place to..."},{"start":380.79,"end":383.04,"text":"...Miss Pepper!"},{"start":383.24,"end":385.28,"text":"For her wonderful potion!"},{"start":386.02,"end":387.33,"text":"Huh, in fact..."},{"start":387.58,"end":389.29,"text":"...it's not really a potion..."},{"start":389.42,"end":392.58,"text":"...it's just my cat's pee sample from his last trip to the vet!"},{"start":393.17,"end":394.17,"text":"Isn't it, Carrot?"},{"start":395.71,"end":396.42,"text":"Meow!"}],"glossary":{"morevna":"Morevna Project (animasyon stüdyosu)","ethic":"Ethic Cinema (yapım ortağının adı)","ufff":"of! (yorgunluk, sıkıntı sesi)","komona":"Komona (şehrin adı)","komona's":"Komona'nın (şehrin adı)","whaaaat":"neee?! (what, şaşkınlıkla uzatılmış)","caaaaaaarrrrrooooooot":"Caaarrot! (Carrot'a öfkeyle bağırış)","technologist's":"Technologist's Union: Teknologlar Birliği","coriander":"Coriander (yarışmacı cadının adı)","coriander's":"Coriander'ın (yarışmacı cadının adı)","saffron":"Saffron (yarışmacı cadının adı)","shichimi":"Shichimi (yarışmacı cadının adı)","o":"applaud-o-meter: alkışölçer","mi":"mi-ra-cu-lous: mucizevi (heceleyerek)","ra":"mi-ra-cu-lous: mucizevi (heceleyerek)","cu":"mi-ra-cu-lous: mucizevi (heceleyerek)","lous":"mi-ra-cu-lous: mucizevi (heceleyerek)","s":"S-sorry: Ö-özür dilerim (kekeleme)"}},{"id":"astronauts-reading-fan-mail","type":"video","title":"Astronauts Reading Fan Mail","creator":"NASA Johnson Space Center","year":2022,"level":"B1","category":"real","durationSeconds":410,"genre":"documentary","summaryTr":"NASA astronotları çocukların gönderdiği mektupları ve çizimleri okuyor: Uzayda peynir var mı? Tavuk nugget nasıl yenir? Astronotlar uzaylılara inanır mı? Samimi, esprili ve gerçek İngilizce konuşmalar.","levelNoteTr":"B1, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî bir CEFR derecesi değildir. Yedi farklı astronot doğal ve hızlı konuşur; günlük ifadeler ve roket, yörünge gibi uzay kelimeleri vardır.","advisoryTr":"Tüm yaşlara uygundur.","videoUrl":"https://images-assets.nasa.gov/video/jsc2022m000279_Astronauts_Reading_Fan_Mail_3-SOCIAL/jsc2022m000279_Astronauts_Reading_Fan_Mail_3-SOCIAL~medium.mp4","qualities":[{"label":"Standart","url":"https://images-assets.nasa.gov/video/jsc2022m000279_Astronauts_Reading_Fan_Mail_3-SOCIAL/jsc2022m000279_Astronauts_Reading_Fan_Mail_3-SOCIAL~medium.mp4","sizeMB":117},{"label":"Yüksek","url":"https://images-assets.nasa.gov/video/jsc2022m000279_Astronauts_Reading_Fan_Mail_3-SOCIAL/jsc2022m000279_Astronauts_Reading_Fan_Mail_3-SOCIAL~large.mp4","sizeMB":253}],"source":{"name":"NASA — Astronauts Reading Fan Mail #3","url":"https://images.nasa.gov/details/jsc2022m000279_Astronauts_Reading_Fan_Mail_3-SOCIAL","license":"Kamu malı (NASA yapımı, ABD'de telife tabi değil)","licenseUrl":"https://www.nasa.gov/nasa-brand-center/images-and-media/","credit":"NASA Johnson Space Center · Jeanette Epps, Kayla Barron, Kjell Lindgren, Megan McArthur, Zena Cardman, Reid Wiseman, Anil Menon"},"subtitleSource":{"name":"NASA — resmî İngilizce SRT altyazısı","url":"https://images-assets.nasa.gov/video/jsc2022m000279_Astronauts_Reading_Fan_Mail_3-SOCIAL/jsc2022m000279_Astronauts_Reading_Fan_Mail_3-SOCIAL.srt","license":"Kamu malı (NASA)","licenseUrl":"https://www.nasa.gov/nasa-brand-center/images-and-media/","changeNoteTr":"NASA'nın tamamı büyük harfli altyazısı okunurluk için normal yazıma çevrildi, kısa parçalar cümle olarak birleştirildi ve bozuk kesme işaretleri düzeltildi; sözler korunmuştur."},"captions":[{"start":0,"end":1.701,"text":"Hi, my name is Jeanette Epps."},{"start":1.701,"end":3.57,"text":"Hi, I'm NASA astronaut, Kayla Barron."},{"start":3.57,"end":7.107,"text":"I am NASA astronaut Kjell Lindgren, and I just got back from the International"},{"start":7.107,"end":8.408,"text":"Space Station a few weeks ago."},{"start":8.408,"end":12.112,"text":"It's awesome to be back with my family and friends, to be back here on the Earth."},{"start":12.112,"end":16.182,"text":"I do love to get real letters, whether it's at home or at work or even in space"},{"start":16.182,"end":19.986,"text":"we get cards and letters delivered from family from time to time, which is so exciting."},{"start":19.986,"end":24.29,"text":"And this year we'd like to thank all the students who sent in letters and notes to us."},{"start":24.29,"end":27.527,"text":"And this is one of my favorite things to do is to read your letters."},{"start":27.527,"end":29.329,"text":"So let's get to it."},{"start":36.202,"end":38.438,"text":"The first time you went into space, how did it feel?"},{"start":38.438,"end":40.173,"text":"Were you scared or happy?"},{"start":40.173,"end":43.309,"text":"My first space launch was incredible."},{"start":43.309,"end":46.913,"text":"We were super well prepared, so I think for the most part we were just"},{"start":46.913,"end":50.75,"text":"executing the procedures, doing the job we had practiced doing."},{"start":50.75,"end":55.455,"text":"But as we counted down, you know, the famous countdown from ten, nine, eight up to that"},{"start":55.455,"end":58.691,"text":"moment of launch, the rocket engines light underneath us."},{"start":58.691,"end":63.029,"text":"And there's kind of this magic moment where you hang in the air, you're just off"},{"start":63.029,"end":66.332,"text":"the launch pad, and you can feel that you're starting to travel to space, but you haven't"},{"start":66.332,"end":68.134,"text":"really started accelerating yet."},{"start":68.134,"end":72.005,"text":"And in that moment, I was just flooded with pure joy."},{"start":72.005,"end":76.843,"text":"I was just so excited that my journey was finally starting and so excited to do it"},{"start":76.843,"end":79.679,"text":"with my teammates, my crew and our team around the world."},{"start":79.679,"end":85.051,"text":"And so, yeah, it was I was happy more than anything else."},{"start":85.051,"end":87.42,"text":"What do we have in here?"},{"start":87.62,"end":91.091,"text":"Look at this."},{"start":91.091,"end":92.692,"text":"That's so good."},{"start":92.692,"end":94.06,"text":"I'm going to put that on my refrigerator."},{"start":94.06,"end":95.462,"text":"Oh, look at this."},{"start":95.462,"end":97.097,"text":"This makes my day."},{"start":97.097,"end":97.73,"text":"How great is that?"},{"start":97.73,"end":99.866,"text":"That's going up on the wall for sure."},{"start":99.866,"end":102.035,"text":"I love those colors. Love it."},{"start":102.469,"end":105.905,"text":"I had a bowl of cereal and milk for breakfast and chili for lunch."},{"start":105.905,"end":108.508,"text":"And every now and then you open these up and you learn what, like,"},{"start":108.508,"end":109.542,"text":"somebody's favorite food is."},{"start":109.542,"end":111.644,"text":"Is there cheese to eat in your spaceship?"},{"start":111.644,"end":112.479,"text":"I love cheese."},{"start":112.479,"end":113.646,"text":"Oh, my gosh. Me too."},{"start":113.646,"end":118.084,"text":"Actually, it's really hard to send cheese to space because it goes bad pretty quickly."},{"start":118.084,"end":121.187,"text":"But you can send some hard cheeses to space, so I really hope that"},{"start":121.187,"end":122.555,"text":"that's there in my spaceship."},{"start":122.555,"end":124.457,"text":"Sara says."},{"start":124.457,"end":129.462,"text":"I think space is very cool, but I think space ice cream would be the best part."},{"start":129.462,"end":134.634,"text":"Sara, you know all that there is to know because you're absolutely right, space"},{"start":134.634,"end":136.536,"text":"ice cream is very cool and cold."},{"start":136.536,"end":138.338,"text":"Do you like chicken nuggets?"},{"start":138.338,"end":139.706,"text":"I love all chicken nuggets."},{"start":139.706,"end":142.242,"text":"I'm sure there's somebody out there that does not like chicken nuggets,"},{"start":142.242,"end":143.176,"text":"but that is not me."},{"start":143.176,"end":147.147,"text":"So I think the bigger chicken nugget question is, how do you eat your chicken nuggets?"},{"start":147.147,"end":149.215,"text":"With a fork, and knife, dip them in ketchup?"},{"start":149.215,"end":151.651,"text":"Are you kind of a mayonnaise or a mustard person?"},{"start":151.651,"end":154.854,"text":"Or is it just straight up, I've got 18 chicken nuggets in front of me"},{"start":154.854,"end":157.223,"text":"and I'm getting after it all right now?"},{"start":157.223,"end":160.593,"text":"So I don't care how you eat yours, but I'll tell you how I eat mine."},{"start":160.593,"end":161.895,"text":"I definitely like chicken nuggets."},{"start":161.895,"end":164.364,"text":"I like a little bit of ketchup and I definitely use my fingers."},{"start":164.364,"end":169.702,"text":"It's a great question and I hope you have a wonderful holiday season, Charlie."},{"start":169.702,"end":172.071,"text":"So what type of rocket ship did you go on?"},{"start":172.071,"end":176.509,"text":"Well, this most recent mission, I flew in a Crew Dragon capsule"},{"start":176.509,"end":178.578,"text":"on top of a Falcon-9 rocket."},{"start":178.578,"end":179.746,"text":"It was absolutely amazing."},{"start":179.746,"end":183.116,"text":"We launched from Kennedy Space Center and we were in low Earth orbit"},{"start":183.116,"end":184.417,"text":"in less than nine minutes."},{"start":184.417,"end":188.221,"text":"Now, my first mission about seven years ago, I launched in a Soyuz capsule"},{"start":188.221,"end":192.225,"text":"on a Soyuz rocket out of baikonur cosmodrome in Kazakhstan."},{"start":192.225,"end":196.496,"text":"I launched with our Russian partners and, and that was my first flight."},{"start":196.496,"end":201.034,"text":"And so it was really cool to have that experience of flying into space"},{"start":201.034,"end":202.936,"text":"on two different types of rockets."},{"start":202.936,"end":204.671,"text":"What's your favorite thing about your job?"},{"start":204.671,"end":209.842,"text":"Well, Piper, one of my favorite things about my job is that I continue to learn new things"},{"start":209.842,"end":210.81,"text":"just about every day."},{"start":210.81,"end":215.081,"text":"Flying in the T-38, doing robotics, just about everything that we do here."},{"start":215.081,"end":216.549,"text":"There's always something new going on."},{"start":216.549,"end":217.283,"text":"And I like to learn."},{"start":217.283,"end":217.784,"text":"This is cool."},{"start":217.784,"end":219.452,"text":"This is a launch pad."},{"start":219.452,"end":220.954,"text":"Look at that."},{"start":220.987,"end":222.956,"text":"Very detailed from Gabe."},{"start":222.956,"end":224.49,"text":"Gabe, that's awesome."},{"start":224.49,"end":224.857,"text":"I see."},{"start":224.857,"end":226.259,"text":"We got the, we got the pad here."},{"start":226.259,"end":230.93,"text":"We got the gantry that we walk across into the capsule there with the astronauts inside."},{"start":230.93,"end":233.166,"text":"That is a great drawing, Gabe. Good job."},{"start":233.166,"end":235.101,"text":"Can you feel heat in the spaceship?"},{"start":235.101,"end":236.703,"text":"Especially when we're coming home?"},{"start":236.703,"end":238.738,"text":"The- our spacecraft gets really hot."},{"start":238.738,"end":242.842,"text":"That's why we have a heat shield that protects us as our spacecraft starts to travel"},{"start":242.842,"end":243.643,"text":"through the atmosphere."},{"start":243.643,"end":247.914,"text":"Because all of that resistance of the gases in the atmosphere really cause the,"},{"start":247.914,"end":249.249,"text":"the craft to heat up."},{"start":249.249,"end":253.086,"text":"But we're in suits that give us cooling, so they keep our bodies cool."},{"start":253.086,"end":255.121,"text":"And it's kind of like you have air conditioning."},{"start":255.121,"end":258.791,"text":"So even though the vehicle gets really hot, the spaceship gets really hot, we stay at a"},{"start":258.791,"end":259.792,"text":"comfortable temperature."},{"start":259.792,"end":261.861,"text":"What types of things do we do in outer space?"},{"start":261.861,"end":267.133,"text":"Right now we're in low-Earth orbit, so that's where the space station is."},{"start":267.133,"end":268.901,"text":"We do two main things there."},{"start":268.901,"end":274.641,"text":"One is to keep it functioning and keep it working because it's a complex machine there"},{"start":274.641,"end":275.908,"text":"in low-Earth orbit."},{"start":275.908,"end":279.479,"text":"The other thing we do is we do research there and a lot of our time"},{"start":279.479,"end":284.684,"text":"is trying to understand the human body, understand different things that we need to take"},{"start":284.684,"end":290.089,"text":"the next step to the Moon to stay and after that to Mars."},{"start":290.089,"end":293.826,"text":"And so to keep exploring, we have to keep learning."},{"start":293.826,"end":297.33,"text":"I love not knowing what is inside each of these letters."},{"start":297.33,"end":299.299,"text":"And this one from Evan is really cool."},{"start":299.299,"end":301.034,"text":"The drawings are always my favorite."},{"start":301.034,"end":308.141,"text":"From Abigail in Saint George, Utah used a really awesome cat astronaut sticker here"},{"start":308.141,"end":310.61,"text":"who doesn't love a cat on a flying saucer?"},{"start":310.61,"end":312.445,"text":"Do astronauts believe in aliens?"},{"start":312.445,"end":313.613,"text":"Well, that's a good question."},{"start":313.613,"end":314.18,"text":"I don't know."},{"start":314.18,"end":316.716,"text":"Some maybe do and some maybe don't."},{"start":316.716,"end":320.286,"text":"I think it would be amazing to discover aliens in our lifetime."},{"start":320.286,"end":323.456,"text":"From my perspective, aliens probably don't look like little green men,"},{"start":323.456,"end":327.86,"text":"but they might be like tiny microorganisms that live or used to live on a planet"},{"start":327.86,"end":328.561,"text":"like Mars."},{"start":328.561,"end":331.898,"text":"Unequivocally, 100%, I believe in aliens."},{"start":331.898,"end":335.702,"text":"There is no way that you can be on the space station going around the Earth"},{"start":335.702,"end":340.54,"text":"and look out at night and see millions of stars and not think for certain."},{"start":340.54,"end":343.576,"text":"There are aliens out there and people ask me if I've ever seen an alien."},{"start":343.576,"end":345.378,"text":"And I say absolutely. 100%."},{"start":345.378,"end":347.88,"text":"I've seen aliens because you're looking at them every night."},{"start":347.88,"end":353.152,"text":"When you look out in the night sky, somewhere out there, there is some crazy civilization"},{"start":353.152,"end":355.588,"text":"doing some crazy work that we haven't discovered yet."},{"start":355.588,"end":356.656,"text":"I know it is out there."},{"start":356.656,"end":359.359,"text":"Thank you all so much for the letters that you write to us."},{"start":359.359,"end":363.262,"text":"It means so much to receive them and I love reading every single one."},{"start":363.262,"end":364.43,"text":"Thank you."},{"start":364.43,"end":367.6,"text":"These letters are the rocket fuel that we use."},{"start":367.6,"end":369.135,"text":"This is what keeps us going."},{"start":369.135,"end":373.573,"text":"So please don't stop sending them, please keep sending them and help us push this"},{"start":373.573,"end":374.34,"text":"mission forward."},{"start":374.34,"end":376.342,"text":"Because it's super important."},{"start":376.342,"end":377.143,"text":"Thank you."},{"start":377.143,"end":380.847,"text":"Thanks, everybody, for all your letters and your awesome questions."},{"start":380.847,"end":386.486,"text":"The curiosity is awesome and I hope you stay engaged and thinking about how the world"},{"start":386.486,"end":387.787,"text":"and the universe works."},{"start":387.787,"end":388.821,"text":"Thank you for your letters."},{"start":388.821,"end":389.856,"text":"Keep them coming."},{"start":389.856,"end":391.224,"text":"Have a great holiday."},{"start":391.224,"end":395.161,"text":"I am so thankful to be back here on Earth with my family and friends"},{"start":395.161,"end":399.866,"text":"and I wish you all the best this holiday season as you spend time with your family,"},{"start":399.866,"end":403.136,"text":"with your friends on our incredible planet, our home, the Earth."}],"glossary":{"jeanette":"Jeanette Epps (NASA astronotu)","epps":"Jeanette Epps (NASA astronotu)","nasa":"NASA (ABD Ulusal Havacılık ve Uzay Dairesi)","kayla":"Kayla Barron (NASA astronotu)","barron":"Kayla Barron (NASA astronotu)","kjell":"Kjell Lindgren (NASA astronotu)","lindgren":"Kjell Lindgren (NASA astronotu)","sara":"Sara (mektup yazan çocuğun adı)","charlie":"Charlie (mektup yazan çocuğun adı)","gabe":"Gabe (mektup yazan çocuğun adı)","evan":"Evan (mektup yazan çocuğun adı)","abigail":"Abigail (mektup yazan çocuğun adı)","kennedy":"Kennedy Uzay Merkezi (Florida'daki fırlatma üssü)","soyuz":"Soyuz (Rus uzay kapsülü ve roketi)","baikonur":"Baykonur (Kazakistan'daki uzay üssü)","cosmodrome":"kozmodrom, uzay üssü","kazakhstan":"Kazakistan","utah":"Utah (ABD'de bir eyalet)","t":"T-38 (astronotların eğitim uçağı)"}},{"id":"elephants-dream","type":"video","title":"Elephants Dream","creator":"Blender Foundation","year":2006,"level":"B1","category":"scifi","durationSeconds":654,"genre":"scifi","summaryTr":"Emo ve Proog, tuhaf makinelerle dolu bir dünyada yol alırken gördükleri şeyler konusunda anlaşamaz. Kısa sorular, yön tarifleri ve tekrarlanan günlük ifadelerle dinleme pratiği yap.","levelNoteTr":"B1, İngilizce altyazı ve kelime desteğiyle dinleme için Lantern English tahminidir; resmî bir CEFR derecesi değildir. Konuşmalar çoğunlukla kısa, yavaş ve tekrarlıdır. Soyut olay örgüsünü yorumlamak ve birkaç mecazı anlamak daha ileri düzeyde olabilir; uzun sessiz sahneler vardır.","advisoryTr":"Karanlık ve gerçeküstü görüntüler, tehdit ve fiziksel şiddet içerir; küçük çocuklar için uygun olmayabilir.","videoUrl":"https://video.blender.org/object-storage/web_videos/cccc3e60-0291-4ecc-aa56-39b2e2c7d0d5-720.mp4","qualities":[{"label":"240p","url":"https://video.blender.org/object-storage/web_videos/cccc3e60-0291-4ecc-aa56-39b2e2c7d0d5-240.mp4","sizeMB":31},{"label":"360p","url":"https://video.blender.org/object-storage/web_videos/cccc3e60-0291-4ecc-aa56-39b2e2c7d0d5-360.mp4","sizeMB":50},{"label":"480p","url":"https://video.blender.org/object-storage/web_videos/cccc3e60-0291-4ecc-aa56-39b2e2c7d0d5-480.mp4","sizeMB":70},{"label":"720p","url":"https://video.blender.org/object-storage/web_videos/cccc3e60-0291-4ecc-aa56-39b2e2c7d0d5-720.mp4","sizeMB":117}],"source":{"name":"Blender Foundation — Elephants Dream","url":"https://orange.blender.org/","license":"CC BY 2.5","licenseUrl":"https://creativecommons.org/licenses/by/2.5/","credit":"(CC) Blender Foundation / Netherlands Media Art Institute | orange.blender.org","licenseSourceUrl":"https://orange.blender.org/blog/creative-commons-license-2/","watchUrl":"https://video.blender.org/videos/watch/cccc3e60-0291-4ecc-aa56-39b2e2c7d0d5","creditNoteTr":"Film, kapanış jeneriğiyle birlikte resmî Blender kaynağından değiştirilmeden oynatılır."},"subtitleSource":{"name":"Wikimedia Commons katkıda bulunanları — İngilizce altyazı","url":"https://commons.wikimedia.org/wiki/TimedText:Elephants_Dream.ogv.en.srt","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","credit":"Wikimedia Commons katkıda bulunanları (yazarlar kaynak sayfasının geçmişinde)","changeNoteTr":"Altyazı sözleri korunmuş; biçim etiketleri kaldırılıp zamanlar saniyeye dönüştürülmüştür. Üç küçük zaman çakışmasının bitişleri en fazla 0,009 saniye kısaltılmıştır."},"glossary":{"emo":"Emo (karakter adı)","proog":"Proog (karakter adı)","snarlers":"hırlayan şeyler; filmde hayalî makine adı","pulp":"posa; burada ezilmiş bir kütle","ground":"ezilmiş, öğütülmüş","sick":"hasta; burada rahatsız, dengesiz","babylon":"Babil","colossus":"dev heykel","rhodes":"Rodos","clockwork":"saat mekanizması; kusursuz işleyiş","hah":"hah! (ünlem)","b":"but kelimesinde kekeleme (ama)","n":"no kelimesinde kekeleme (hayır)"},"captions":[{"start":15,"end":18.13,"text":"At the left we can see…"},{"start":18.13,"end":20.5,"text":"At the right we can see the—"},{"start":20.5,"end":21.98,"text":"…the head-snarlers."},{"start":21.98,"end":24.55,"text":"Everything is safe… Perfectly safe."},{"start":24.55,"end":25.77,"text":"Emo?"},{"start":26.12,"end":27.22,"text":"Emo?"},{"start":28.62,"end":30.104,"text":"Watch out!"},{"start":46.56,"end":48.26,"text":"Are you hurt?"},{"start":51.99,"end":54.2,"text":"I don’t think so. You?"},{"start":55.52,"end":57.09,"text":"I’m OK."},{"start":57.09,"end":61.11,"text":"Get up, Emo! It’s not safe here."},{"start":62.03,"end":63.22,"text":"Let’s go."},{"start":63.22,"end":65.19,"text":"What’s next?"},{"start":65.19,"end":66.96,"text":"You’ll see!"},{"start":67.68,"end":68.84,"text":"You’ll see!"},{"start":76.03,"end":78.48,"text":"Emo! This way."},{"start":94.22999999999999,"end":95.47999999999999,"text":"Follow me!"},{"start":131.1,"end":132.52100000000002,"text":"Hurry, Emo!"},{"start":168.438,"end":170.063,"text":"You’re not paying attention!"},{"start":170.063,"end":174.31,"text":"I–I just want to answer the phone."},{"start":174.31,"end":177.04,"text":"Emo, look… I mean, listen."},{"start":179.14,"end":182,"text":"You have to learn to listen."},{"start":183.14,"end":185.04,"text":"This is not some game."},{"start":185.04,"end":189.18,"text":"You… I mean, we. We could easily die out here."},{"start":190.01,"end":194.39600000000002,"text":"Listen… Listen to the sounds of the machine."},{"start":198.05,"end":200,"text":"Listen to your breathing."},{"start":266.646,"end":269.313,"text":"Well, don’t you ever get tired of this?"},{"start":269.313,"end":271.09,"text":"Tired?!"},{"start":271.09,"end":273.31,"text":"Emo, the machine is like…"},{"start":273.31,"end":275.26,"text":"Like clockwork!"},{"start":275.26,"end":277.063,"text":"One move out of place…"},{"start":277.063,"end":279.12,"text":"…and you’re ground to a pulp."},{"start":280.95,"end":282.104,"text":"But isn’t it—"},{"start":282.104,"end":286.03,"text":"Pulp, Emo! Is that what you want? Pulp?"},{"start":287.104,"end":290.42,"text":"Emo, your goal in life…"},{"start":290.44,"end":291.95,"text":"…pulp?!"},{"start":341.31,"end":343.42,"text":"Emo, close your eyes."},{"start":344.15,"end":345.396,"text":"–Why?\n–Now!"},{"start":351.15,"end":351.97,"text":"OK."},{"start":353.11,"end":354.68,"text":"Good."},{"start":359.42,"end":362.1,"text":"What do you see at your left side, Emo?"},{"start":364.02,"end":366,"text":"–Nothing.\n–Really?"},{"start":366,"end":367.58,"text":"No, nothing at all."},{"start":367.58,"end":371.98,"text":"Really? A–And at your right? What do you see at your right side, Emo?"},{"start":373.31,"end":376.84,"text":"The same, Proog. Exactly the same…"},{"start":376.84,"end":379.896,"text":"–…nothing!\n–Great."},{"start":399.97,"end":402.72,"text":"Listen, Proog! Do you hear that?"},{"start":403.44,"end":404.56,"text":"Can we go here?"},{"start":405.063,"end":406.56,"text":"–There?\n–Yeah!"},{"start":406.58,"end":408.188,"text":"It isn’t safe, Emo."},{"start":409.14,"end":412.01,"text":"–B–But…\n–Trust me, it’s not."},{"start":413.02,"end":414.17,"text":"Well, maybe I could…"},{"start":414.17,"end":415.146,"text":"No."},{"start":417.1,"end":418.82,"text":"–But…\n–No!"},{"start":418.82,"end":420.24,"text":"No!"},{"start":420.771,"end":423.05,"text":"Any further questions, Emo?"},{"start":423.97,"end":425.09,"text":"N–No."},{"start":429.05,"end":430.08,"text":"Emo?"},{"start":431.14,"end":433.08,"text":"Emo, why?!"},{"start":433.08,"end":435.36,"text":"Emo, why…?"},{"start":435.36,"end":438.84,"text":"Why can’t you see the beauty of this place?"},{"start":438.84,"end":440.646,"text":"The way it works."},{"start":440.646,"end":443.92,"text":"How… How perfect it is."},{"start":443.92,"end":447.04,"text":"No, Proog, I don’t see."},{"start":447.04,"end":449.97,"text":"I don’t see because there’s nothing there."},{"start":451.05,"end":455.24,"text":"And why should I trust my life to something that isn’t there?"},{"start":455.24,"end":456.6,"text":"Well, can you tell me that?"},{"start":456.6,"end":457.38,"text":"Emo…"},{"start":457.38,"end":458.92,"text":"Answer me!"},{"start":462.97,"end":464,"text":"Proog…"},{"start":465.05,"end":466.854,"text":"…you’re a sick man!"},{"start":466.854,"end":468.90999999999997,"text":"Stay away from me!"},{"start":472.188,"end":474.854,"text":"No! Emo! It’s a trap!"},{"start":475.42,"end":476.979,"text":"Hah, “it’s a trap!”"},{"start":476.979,"end":481.229,"text":"At the left side you can see the Hanging Gardens of Babylon!"},{"start":481.96,"end":483.95,"text":"How’s that for a trap?"},{"start":485.72,"end":486.92,"text":"No, Emo."},{"start":489,"end":492.64,"text":"At the right side you can see—well guess what…"},{"start":492.64,"end":494.66,"text":"…the Colossus of Rhodes!"},{"start":495.32,"end":496.39,"text":"No!"},{"start":496.396,"end":500.16,"text":"The Colossus of Rhodes! And it is here just for you, Proog."},{"start":500.16,"end":501.688,"text":"Just for you!"},{"start":531,"end":533.021,"text":"It is there…"},{"start":533.021,"end":536.04,"text":"I’m telling you, Emo…"},{"start":537,"end":539.86,"text":"…it is… there…"}]},{"id":"how-big-is-space","type":"video","title":"How Big Is Space? We Asked a NASA Expert","creator":"NASA","year":2025,"level":"B1","category":"real","durationSeconds":96,"genre":"education","summaryTr":"Bir NASA bilim insanı tek bir soruyu cevaplıyor: Uzay ne kadar büyük? Işık yılı, galaksiler ve evrenin sınırı hakkında bir buçuk dakikalık, hızlı ve anlaşılır bir açıklama.","levelNoteTr":"B1, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî bir CEFR derecesi değildir. Konuşma açık ve tempolu; light-year, galaxy, observable gibi bilim kelimeleri vardır.","advisoryTr":"Tüm yaşlara uygundur.","videoUrl":"https://images-assets.nasa.gov/video/How%20Big%20is%20Space/How%20Big%20is%20Space~medium.mp4","qualities":[{"label":"Standart","url":"https://images-assets.nasa.gov/video/How%20Big%20is%20Space/How%20Big%20is%20Space~medium.mp4","sizeMB":25},{"label":"Yüksek","url":"https://images-assets.nasa.gov/video/How%20Big%20is%20Space/How%20Big%20is%20Space~large.mp4","sizeMB":55}],"source":{"name":"NASA — How Big is Space? We Asked a NASA Expert","url":"https://images.nasa.gov/details/How%20Big%20is%20Space","license":"Kamu malı (NASA yapımı, ABD'de telife tabi değil)","licenseUrl":"https://www.nasa.gov/nasa-brand-center/images-and-media/","credit":"NASA · A NASA 360 Production"},"subtitleSource":{"name":"NASA — resmî İngilizce SRT altyazısı","url":"https://images-assets.nasa.gov/video/How%20Big%20is%20Space/How%20Big%20is%20Space.srt","license":"Kamu malı (NASA)","licenseUrl":"https://www.nasa.gov/nasa-brand-center/images-and-media/","changeNoteTr":"Altyazı sözleri korunmuş; zamanlar saniyeye dönüştürülmüştür."},"captions":[{"start":0,"end":3.136,"text":"How big is space?"},{"start":3.67,"end":5.171,"text":"We Asked a NASA Scientist."},{"start":5.171,"end":7.474,"text":"Space is really big."},{"start":7.474,"end":10.844,"text":"Thinking about our solar system, let's imagine you could get in a car"},{"start":10.844,"end":13.146,"text":"and drive to Pluto at highway speeds."},{"start":13.146,"end":15.782,"text":"It would take you about 6,000 years to get there."},{"start":15.782,"end":19.252,"text":"When we start to think about other stars outside of our solar system,"},{"start":19.252,"end":22.022,"text":"we need to think about another unit of distance."},{"start":22.022,"end":24.958,"text":"This is why astronomers use the unit light-years."},{"start":24.958,"end":28.228,"text":"Light travels at 186,000 miles per second."},{"start":28.528,"end":31.531,"text":"One light year is about 6 trillion miles."},{"start":31.664,"end":35.101,"text":"The closest star to our Sun is about four light years away."},{"start":35.869,"end":40.373,"text":"Our own Milky Way galaxy is about 100,000 light-years across."},{"start":40.44,"end":43.576,"text":"We know from deep field images of the universe that there are hundreds"},{"start":43.576,"end":46.579,"text":"of billions, perhaps a trillion other galaxies."},{"start":46.713,"end":49.482,"text":"Using some of the deepest images yet from JWST,"},{"start":49.516,"end":51.017,"text":"we've been able to see galaxies"},{"start":51.017,"end":54.02,"text":"that emitted their light about 13 and a half billion years ago."},{"start":54.354,"end":58.158,"text":"Now, here's a really important thing. Because the universe is expanding,"},{"start":58.191,"end":59.859,"text":"those most distant galaxies"},{"start":59.859,"end":63.696,"text":"are actually much further away than 13 and a half billion light years."},{"start":64.23,"end":67.934,"text":"I'm glossing over some math here, but we can estimate that the observable"},{"start":67.934,"end":71.704,"text":"universe is about 92 billion light-years across."},{"start":72.105,"end":75.742,"text":"But we're pretty sure that the universe is even bigger than what we can see."},{"start":76.309,"end":78.511,"text":"And here's where things get really weird,"},{"start":78.511,"end":82.248,"text":"we don't actually know if the universe is finite or infinite."},{"start":82.649,"end":86.252,"text":"As much as we've learned about the universe, science has no reliable"},{"start":86.252,"end":89.322,"text":"estimate of the actual size of the entire universe."},{"start":89.889,"end":91.925,"text":"We Asked a NASA Scientist."},{"start":91.925,"end":96.029,"text":"NASA. A NASA 360 Production."}],"glossary":{"nasa":"NASA (ABD Ulusal Havacılık ve Uzay Dairesi)","pluto":"Plüton (cüce gezegen)","milky":"Milky Way: Samanyolu galaksisi","jwst":"JWST: James Webb Uzay Teleskobu"}},{"id":"morevna-episode-3","type":"video","title":"Morevna: Episode 3 — Underground","creator":"Morevna Project","year":2018,"level":"B1","category":"adventure","durationSeconds":617,"genre":"fantasy","summaryTr":"Rus masalı Marya Morevna'nın bilim kurgu dünyasında geçen anime tarzı uyarlaması. Marya malikânesinden çıkarken tamirci Ivan'a tüm anahtarları bırakır ve tek bir kapıyı açmamasını tembihler. Ivan merakına yenik düşer.","levelNoteTr":"B1, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî bir CEFR derecesi değildir. Konuşmalar kısa ama hızlıdır; telsiz konuşmaları, emir cümleleri ve teknik kelimeler vardır.","advisoryTr":"Çizgi film tarzı dövüş ve silah sahneleri, hafif argo (\"damn\") içerir. Dizinin 3. bölümüdür ve merak uyandıran açık bir sonla biter.","videoUrl":"https://peertube.touhoppai.moe/static/web-videos/4adb3a75-6784-4e99-8a5d-66d13578ba9d-720.mp4","qualities":[{"label":"360p","url":"https://peertube.touhoppai.moe/static/web-videos/4adb3a75-6784-4e99-8a5d-66d13578ba9d-360.mp4","sizeMB":29},{"label":"720p","url":"https://peertube.touhoppai.moe/static/web-videos/4adb3a75-6784-4e99-8a5d-66d13578ba9d-720.mp4","sizeMB":59},{"label":"1080p","url":"https://peertube.touhoppai.moe/static/web-videos/4adb3a75-6784-4e99-8a5d-66d13578ba9d-1080.mp4","sizeMB":112}],"source":{"name":"Morevna Project — Morevna Episode 3 (English)","url":"https://morevnaproject.org/","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","credit":"Morevna Project · Adamant Art School of Gorno-Altaisk ile birlikte","watchUrl":"https://peertube.touhoppai.moe/videos/watch/4adb3a75-6784-4e99-8a5d-66d13578ba9d"},"subtitleSource":{"name":"Morevna Project — İngilizce SRT altyazısı","url":"https://raw.githubusercontent.com/morevnaproject/subtitles-translation/master/output/morevna-ep3/morevna-ep3-eng.srt","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","changeNoteTr":"Altyazı sözleri korunmuş; biçim etiketleri kaldırılıp zamanlar saniyeye dönüştürülmüştür."},"captions":[{"start":0.36,"end":2.4,"text":"Morevna Project..."},{"start":2.88,"end":7,"text":"...in association with \"Adamant\" Art School of Gorno-Altaisk..."},{"start":7.44,"end":9.24,"text":"presents"},{"start":26.4,"end":30.4,"text":"\"Falcon\", \"Falcon\", respond. This is \"Hawk\". What's your status?"},{"start":55,"end":57.68,"text":"Hey officer, can I help you somehow?"},{"start":59.92,"end":61.56,"text":"Stay away, stay away!"},{"start":61.72,"end":63.6,"text":"I am a government agent!"},{"start":64.56,"end":67.12,"text":"I know, I know..."},{"start":67.84,"end":70.56,"text":"And I am the owner of this mansion."},{"start":72.96,"end":78.96,"text":"Episode 3: Underground"},{"start":99.48,"end":105.04,"text":"Ah, Marya Morevna, I just don't get it. We aren't that rich..."},{"start":105.8,"end":109.56,"text":"...but they are coming here like bees to a..."},{"start":109.8,"end":111.36,"text":"...honeypot!"},{"start":111.8,"end":113.56,"text":"I am not a bee, I am a \"Hawk\"."},{"start":113.84,"end":115.6,"text":"Spread your wings, Hawk."},{"start":118.36,"end":120.36,"text":"But it seems like you're having fun."},{"start":120.64,"end":122.2,"text":"Of course I am!"},{"start":122.64,"end":125.16,"text":"But still, why did you drop my favorite toolbox on him?"},{"start":141.16,"end":144.72,"text":"I just can't figure out what you did to them if they're after you so much..."},{"start":145.16,"end":147.16,"text":"I have no idea."},{"start":147.72,"end":149.28,"text":"Going somewhere?"},{"start":149.6,"end":152.24,"text":"I am going to a biker party, and I won't be back until tomorrow."},{"start":152.44,"end":155.16,"text":"Dinner on plate, firewood in shed, dog food under sink..."},{"start":155.44,"end":156.68,"text":"Do we have dogs here?"},{"start":156.92,"end":161.68,"text":"...in case of a power outage, turn on the electric generator and don't forget to restart the air defense system."},{"start":161.88,"end":164.12,"text":"Here are the keys to all of the doors in the mansion."},{"start":164.24,"end":168.56,"text":"Feel free to go anywhere, but don't touch this key and don't unlock the door."},{"start":168.84,"end":169.6,"text":"But why?"},{"start":169.84,"end":172.16,"text":"Just don't!"},{"start":173.36,"end":175.12,"text":"Well, bye..."},{"start":191.2,"end":195.76,"text":"So dear, now I can have some fun with you then."},{"start":233,"end":235.44,"text":"Hm, it seems this lovely evening is in danger."},{"start":242.36,"end":246.68,"text":"Stay here, I'll be right back."},{"start":248.68,"end":251.24,"text":"Caption on the door: \"Cellar\""},{"start":277.2,"end":279.4,"text":"Aha, here it is!"},{"start":285.84,"end":287.2,"text":"What?"},{"start":297.72,"end":299.84,"text":"Could it be..."},{"start":303.12,"end":307.08,"text":"...feel free to go anywhere, but don't touch this key..."},{"start":353.32,"end":355.68,"text":"Hey, is anybody here?"},{"start":358.04,"end":360.92,"text":"There is something wrong with your engine here."},{"start":364.32,"end":366.8,"text":"Damn you…"},{"start":367.52,"end":370.36,"text":"Ah? Who is it?"},{"start":374.28,"end":377.32,"text":"Come on..."},{"start":381.52,"end":386.28,"text":"My name is Ivan Tsarevich... and I am very good at fixing things."},{"start":390.04,"end":391.64,"text":"Inside..."},{"start":398.96,"end":401.16,"text":"There..."},{"start":405.12,"end":410.4,"text":"The framework is quite unusual. It will be a challenge to get inside."},{"start":411.8,"end":414.12,"text":"So, let's start!"},{"start":418.24,"end":420.84,"text":"Yes..."},{"start":423.92,"end":426.4,"text":"Excellent..."},{"start":428.96,"end":431.12,"text":"Well done."},{"start":434.4,"end":437.6,"text":"Certainly, you've got talent..."},{"start":439.16,"end":442.24,"text":"This is not the hardest one..."},{"start":442.48,"end":446.08,"text":"Still, it's quite strange that it's so tricky to open this thing..."},{"start":452.56,"end":453.72,"text":"Well, that's all."},{"start":454.6,"end":457.24,"text":"Open Sesame!"},{"start":480.72,"end":485.48,"text":"What's up? You are almost there!"},{"start":486.16,"end":494.52,"text":"I don't know... there seems to be some piece of paper here... I'm going to remove it now."},{"start":574.88,"end":576.04,"text":"Oh, no..."}],"glossary":{"morevna":"Morevna (Marya Morevna, Rus masal kahramanı)","marya":"Marya Morevna (Rus masal kahramanı)","adamant":"Adamant (sanat okulunun adı)","gorno":"Gorno-Altaysk (Rusya'da bir şehir)","altaisk":"Gorno-Altaysk (Rusya'da bir şehir)","ivan":"Ivan Tsarevich (masaldaki prens)","tsarevich":"Tsarevich: çar oğlu, prens","hm":"hımm (düşünme sesi)","sesame":"Open Sesame: Açıl susam açıl!"}},{"id":"sintel","type":"video","title":"Sintel","creator":"Blender Foundation","year":2010,"level":"B1","category":"adventure","durationSeconds":888,"genre":"fantasy","summaryTr":"Sintel, yaralı bir yavru ejderhayla dost olur. Dostunu aramak için çıktığı yolculuk, onu uzak ve tehlikeli topraklara götürür.","levelNoteTr":"B1, Lantern English'in İngilizce altyazı desteğiyle izleme için yaptığı tahmini değerlendirmedir; resmî bir CEFR derecesi değildir. Kısa diyaloglar ve görsel anlatım takibi kolaylaştırır. Bazı fantastik kelimeler ve mecazlar sözlük desteği gerektirebilir.","advisoryTr":"Fantastik çatışma, yaralanma ve ölüm içeren üzücü sahneler bulunur.","videoUrl":"https://video.blender.org/object-storage/web_videos/0eb052d0-fd51-43e6-aa33-ecdbf77a5d40-720.mp4","qualities":[{"label":"240p","url":"https://video.blender.org/object-storage/web_videos/0eb052d0-fd51-43e6-aa33-ecdbf77a5d40-240.mp4","sizeMB":49},{"label":"360p","url":"https://video.blender.org/object-storage/web_videos/0eb052d0-fd51-43e6-aa33-ecdbf77a5d40-360.mp4","sizeMB":84},{"label":"480p","url":"https://video.blender.org/object-storage/web_videos/0eb052d0-fd51-43e6-aa33-ecdbf77a5d40-480.mp4","sizeMB":120},{"label":"720p","url":"https://video.blender.org/object-storage/web_videos/0eb052d0-fd51-43e6-aa33-ecdbf77a5d40-720.mp4","sizeMB":200},{"label":"1080p","url":"https://video.blender.org/object-storage/web_videos/0eb052d0-fd51-43e6-aa33-ecdbf77a5d40-818.mp4","sizeMB":239}],"source":{"name":"Blender Foundation — Sintel / Durian Open Movie Project","url":"https://durian.blender.org/download/","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0/","credit":"© copyright Blender Foundation | durian.blender.org","licenseSourceUrl":"https://durian.blender.org/sharing/","watchUrl":"https://video.blender.org/w/2PcJe5aZqozRvH7MJ8BTmC","creditNoteTr":"Film, sonundaki tam jenerik korunarak resmî Blender kaynağından oynatılır. Film ve İngilizce altyazı metni değiştirilmemiştir; altyazı zamanları site için sayısal biçime dönüştürülmüştür. Türkçe öğrenme açıklamaları Lantern English tarafından hazırlanmıştır."},"subtitleSource":{"name":"Sintel — resmî İngilizce SRT altyazısı","url":"https://durian.blender.org/wp-content/content/subtitles/sintel_en.srt","license":"CC BY 3.0"},"glossary":{"unprepared":"hazırlıksız","scales":"Scales: Sintel'in ejderha dostunun adı (kelime anlamı: pullar)","sintel":"Sintel: filmin ana karakterinin adı","kindred":"benzer duygu ve düşünceleri paylaşan, yakın","spirit":"ruh; burada kindred spirit: ruh ikizi, yakın hissettiğin kişi","gatekeepers":"geçitlerin veya kapıların bekçileri","blade":"bıçak veya kılıcın keskin kısmı","shed":"dökmek; shed blood: kan dökmek","dear":"çok sevilen, değerli","quest":"uzun ve zorlu arayış","shhh":"şşşt, sessiz ol"},"captions":[{"start":107.25,"end":110.5,"text":"This blade has a dark past."},{"start":111.8,"end":115.8,"text":"It has shed much innocent blood."},{"start":118,"end":121.45,"text":"You're a fool for traveling alone,\nso completely unprepared."},{"start":121.75,"end":124.8,"text":"You're lucky your blood's still flowing."},{"start":125.25,"end":126.3,"text":"Thank you."},{"start":127.5,"end":129,"text":"So..."},{"start":129.4,"end":133.8,"text":"What brings you to\nthe land of the gatekeepers?"},{"start":135,"end":137.5,"text":"I'm searching for someone."},{"start":138,"end":142.2,"text":"Someone very dear?\nA kindred spirit?"},{"start":143.4,"end":145,"text":"A dragon."},{"start":148.85,"end":151.75,"text":"A dangerous quest for a lone hunter."},{"start":152.95,"end":155.87,"text":"I've been alone for\nas long as I can remember."},{"start":207.25,"end":210.5,"text":"We're almost done. Shhh..."},{"start":210.75,"end":213.5,"text":"Hey, sit still."},{"start":228.25,"end":232.25,"text":"Good night, Scales."},{"start":250.35,"end":253.85,"text":"Get him, Scales! Come on!"},{"start":265.25,"end":268.25,"text":"Scales?"},{"start":304,"end":307.5,"text":"Yeah! Come on!"},{"start":338.75,"end":342,"text":"Scales!"},{"start":445.85,"end":447.5,"text":"I have failed."},{"start":452.8,"end":456.5,"text":"You've only failed to see..."},{"start":457.8,"end":460.5,"text":"These are dragon lands, Sintel."},{"start":460.85,"end":464,"text":"You are closer than you know."},{"start":557.6,"end":559.5,"text":"Scales!"},{"start":621.6,"end":624,"text":"Scales?"},{"start":626.2,"end":629.8,"text":"Scales..."}]},{"id":"tears-of-steel","type":"video","title":"Tears of Steel","creator":"Blender Foundation","year":2012,"level":"B1","category":"scifi","durationSeconds":734,"genre":"scifi","summaryTr":"Bir bilim kurgu çekim platosunda eski bir aşkın hesaplaşması, robotlar ve zamana karşı yarış iç içe geçer. Konuşmalar günlük dilde ve sahne sahne ilerler.","levelNoteTr":"B1, Lantern English'in İngilizce altyazı desteğiyle izleme için yaptığı tahmini değerlendirmedir; resmî bir CEFR derecesi değildir. Konuşmalar günlük dildedir; birkaç argo ve sinema terimi (ad-lib, abort, cut) sözlük desteği gerektirebilir. Sintel'e göre konuşma daha yoğundur ve daha uzun diyaloglar içerir.","advisoryTr":"Bilim kurgu aksiyonu ve robot saldırısı sahneleri vardır. Konuşmalarda hafif argo ve küfür geçer.","videoUrl":"https://video.blender.org/object-storage/web_videos/8533ea43-4271-4a57-9694-e9d0b35e1aa1-720.mp4","qualities":[{"label":"240p","url":"https://video.blender.org/object-storage/web_videos/8533ea43-4271-4a57-9694-e9d0b35e1aa1-240.mp4","sizeMB":50},{"label":"360p","url":"https://video.blender.org/object-storage/web_videos/8533ea43-4271-4a57-9694-e9d0b35e1aa1-360.mp4","sizeMB":86},{"label":"480p","url":"https://video.blender.org/object-storage/web_videos/8533ea43-4271-4a57-9694-e9d0b35e1aa1-480.mp4","sizeMB":122},{"label":"720p","url":"https://video.blender.org/object-storage/web_videos/8533ea43-4271-4a57-9694-e9d0b35e1aa1-720.mp4","sizeMB":225},{"label":"1080p","url":"https://video.blender.org/object-storage/web_videos/8533ea43-4271-4a57-9694-e9d0b35e1aa1-800.mp4","sizeMB":248}],"source":{"name":"Blender Foundation — Tears of Steel / Mango Open Movie Project","url":"https://mango.blender.org/","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0/","credit":"(CC) Blender Foundation | mango.blender.org","licenseSourceUrl":"https://mango.blender.org/sharing/","watchUrl":"https://video.blender.org/videos/watch/8533ea43-4271-4a57-9694-e9d0b35e1aa1","creditNoteTr":"Film, kapanış jeneriğiyle birlikte resmî Blender kaynağından oynatılır. Film ve İngilizce altyazı metni değiştirilmemiştir; altyazı zamanları site için sayısal biçime dönüştürülmüştür. Türkçe öğrenme açıklamaları Lantern English tarafından hazırlanmıştır."},"subtitleSource":{"name":"Tears of Steel — resmî İngilizce SRT altyazısı (TOS-en.srt)","url":"https://download.blender.org/demo/movies/ToS/subtitles/TOS-en.srt","license":"CC BY 3.0"},"glossary":{"jerk":"aşağılık herif, hıyar","passions":"tutkular","robotics":"robot bilimi, robotik","freaked":"korkmuş, tedirgin olmuş (freak out)","freaky":"ürkütücü, tuhaf","claws":"pençeler","synced":"senkronize edildi","overwrite":"üzerine yazma","abort":"iptal etmek, yarıda kesmek","tender":"nazik, şefkatli","crush":"ezmek, ezip geçmek","rockstar":"rock yıldızı; çok başarılı kişi","vivacissimo":"müzik terimi: çok canlı ve hızlı","captain":"kaptan"},"captions":[{"start":23,"end":24.5,"text":"You're a jerk, Thom."},{"start":25,"end":27,"text":"Look Celia, we have to follow our passions;"},{"start":27,"end":30.5,"text":"...you have your robotics, and I\njust want to be awesome in space."},{"start":30.8,"end":34,"text":"Why don't you just admit that\nyou're freaked out by my robot hand?"},{"start":34.5,"end":36,"text":"I'm not freaked out by- it's..."},{"start":37,"end":38,"text":"...alright! Fine!"},{"start":38,"end":41,"text":"I'm freaked out! I have nightmares\nthat I'm being chased..."},{"start":41,"end":42,"text":"...by these giant robotic claws of death..."},{"start":42.2,"end":45,"text":"\"Fourty years later\"\nWhatever, Thom. We're done."},{"start":50,"end":53.5,"text":"Robot's memory synced and locked!"},{"start":61,"end":63,"text":"This is pretty freaky."},{"start":117,"end":119,"text":"Shouldn't you be down there?"},{"start":131,"end":133,"text":"I heard you guys talking last night."},{"start":136,"end":138,"text":"It's not my fault, you know."},{"start":191,"end":192,"text":"Are you ready?"},{"start":193,"end":195,"text":"Of course you're ready, you're a rockstar."},{"start":197,"end":198,"text":"How's it looking, Barley?"},{"start":199,"end":201,"text":"We should have about ten minutes..."},{"start":201.5,"end":203,"text":"Well that's perfect."},{"start":203.5,"end":206.5,"text":"We're on in one! All systems go!\nYeah you, go!"},{"start":208,"end":212,"text":"Go! Move your asses! Go go go!"},{"start":213,"end":217,"text":"I love it! Come on, go!"},{"start":223,"end":224,"text":"That's nice."},{"start":224.5,"end":225.7,"text":"Nothing to worry about."},{"start":226,"end":227,"text":"Thom."},{"start":231,"end":233,"text":"There she is."},{"start":233.5,"end":234.5,"text":"Now."},{"start":235,"end":236,"text":"You love her."},{"start":237,"end":238.5,"text":"She is your passion!"},{"start":240,"end":241,"text":"Be tender to her."},{"start":241.5,"end":244.5,"text":"Be honest! Eh- be tender."},{"start":245,"end":248,"text":"Remind her what love is."},{"start":292,"end":295,"text":"...and, action!"},{"start":296.5,"end":298,"text":"Memory overwrite in progress!"},{"start":299,"end":301,"text":"You're a jerk, Thom!"},{"start":302.5,"end":305,"text":"Ohp- Sorry! Sorry."},{"start":316,"end":317,"text":"Look Celia."},{"start":318,"end":320,"text":"We have to follow our passions."},{"start":321,"end":323,"text":"You have your robotics..."},{"start":325,"end":328,"text":"...and I just want to be awesome in space."},{"start":339,"end":341,"text":"Okay, they're coming. Two minutes left!"},{"start":343,"end":344,"text":"Speed it up, Thom!"},{"start":345,"end":346,"text":"Vivacissimo!"},{"start":347,"end":350,"text":"Why don't you just admit that you're\nfreaked out by my robot hand?"},{"start":356,"end":359,"text":"Listen Celia, I was young..."},{"start":359.5,"end":361,"text":"...and a dick."},{"start":361,"end":363,"text":"But that's no reason to\ndestroy the world."},{"start":365,"end":366,"text":"Why does he do this?"},{"start":366.5,"end":368.5,"text":"We already tried that one!"},{"start":371.5,"end":372.5,"text":"Abort!"},{"start":373,"end":374,"text":"Cut!"},{"start":374,"end":375,"text":"Whoaaa!"},{"start":379,"end":380,"text":"Whoaaa!"},{"start":381,"end":383,"text":"Nooooo!"},{"start":383,"end":385,"text":"You broke my heart."},{"start":386,"end":387,"text":"I know."},{"start":387,"end":389,"text":"You forgot me on earth."},{"start":389,"end":390,"text":"I know."},{"start":390.5,"end":393,"text":"I should just crush you."},{"start":396,"end":397,"text":"I'm-"},{"start":407,"end":408,"text":"I'm sorry."},{"start":410,"end":411,"text":"Good ad-lib."},{"start":419,"end":420.5,"text":"Not my fault!"},{"start":422,"end":423,"text":"This time."},{"start":428,"end":429.5,"text":"Quiet on set!"},{"start":430,"end":431,"text":"We're out of time!"},{"start":493,"end":494,"text":"Come on!"},{"start":502,"end":504,"text":"RAAAAAAAAH!"},{"start":504,"end":505,"text":"Memory overwrite, 90%."},{"start":506,"end":508,"text":"Captain! We have to abort!"},{"start":518,"end":520,"text":"The world's changed, Celia..."},{"start":534,"end":536,"text":"...maybe we can too."},{"start":538,"end":539,"text":"Memory overwrite complete!"},{"start":559,"end":560,"text":"You know."},{"start":562,"end":564,"text":"There's a lesson to be learned from this."},{"start":566,"end":567,"text":"Could'a gone worse."}]},{"id":"cosmos-laundromat","type":"video","title":"Cosmos Laundromat: First Cycle","creator":"Blender Foundation","year":2015,"level":"B2","category":"scifi","durationSeconds":730,"genre":"fantasy","summaryTr":"Issız bir adada yaşayan Franck, hayatını değiştirebileceğini söyleyen sıra dışı bir satıcıyla karşılaşır. İmalı konuşmaları, ikna dilini ve günlük deyimleri takip et.","levelNoteTr":"B2, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî bir CEFR derecesi değildir. Günlük ifadelerin yanında ima, alay, mecaz ve satış konuşması vardır. Aksanlar, eksiltili cümleler ve birkaç teknik ifade dinlemeyi zorlaştırır; ilk konuşma yaklaşık 2:20’de başlar.","advisoryTr":"İntihar düşüncesi ve girişimi, ağır küfür ve karanlık temalar içerir. Hassas izleyiciler için uygun olmayabilir; yapımcı hedef kitleyi 13+ olarak belirtir.","videoUrl":"https://video.blender.org/object-storage/web_videos/f507dfdc-e73e-45a4-9778-d758cbe1ce96-720.mp4","qualities":[{"label":"240p","url":"https://video.blender.org/object-storage/web_videos/f507dfdc-e73e-45a4-9778-d758cbe1ce96-240.mp4","sizeMB":43},{"label":"360p","url":"https://video.blender.org/object-storage/web_videos/f507dfdc-e73e-45a4-9778-d758cbe1ce96-360.mp4","sizeMB":76},{"label":"480p","url":"https://video.blender.org/object-storage/web_videos/f507dfdc-e73e-45a4-9778-d758cbe1ce96-480.mp4","sizeMB":110},{"label":"720p","url":"https://video.blender.org/object-storage/web_videos/f507dfdc-e73e-45a4-9778-d758cbe1ce96-720.mp4","sizeMB":201},{"label":"1080p","url":"https://video.blender.org/object-storage/web_videos/f507dfdc-e73e-45a4-9778-d758cbe1ce96-804.mp4","sizeMB":230}],"source":{"name":"Blender Foundation — Cosmos Laundromat: First Cycle","url":"https://gooseberry.blender.org/","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0/","credit":"(CC) Blender Foundation | gooseberry.blender.org","licenseSourceUrl":"https://gooseberry.blender.org/license/","watchUrl":"https://video.blender.org/videos/watch/f507dfdc-e73e-45a4-9778-d758cbe1ce96","creditNoteTr":"Film, kapanış jeneriğiyle birlikte resmî Blender kaynağından değiştirilmeden oynatılır."},"subtitleSource":{"name":"Wikimedia Commons katkıda bulunanları — İngilizce altyazı","url":"https://commons.wikimedia.org/wiki/TimedText:Cosmos_Laundromat_-_First_Cycle_-_Official_Blender_Foundation_release.webm.en-gb.srt","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","credit":"Wikimedia Commons katkıda bulunanları (yazarlar kaynak sayfasının geçmişinde)","changeNoteTr":"Altyazı sözleri korunmuş; biçim etiketleri kaldırılıp zamanlar saniyeye dönüştürülmüştür."},"glossary":{"franck":"Franck (karakter adı)","victor":"Victor (karakter adı)","hector":"Hector (yanlış söylenen ad)","casper":"Casper (yanlış söylenen ad)","hooves":"toynaklar","sheepy":"koyuna ait; burada koyunluk işleri","fucking":"lanet olası (ağır küfür)","tumble":"tamburda döndürme","spin":"sıkma, dönme","variable":"değişken, ayarlanabilir","squeaky":"gıcırdayan; squeaky clean: tertemiz","hehehe":"he he he (gülme sesi)","eh":"ee, hey (ünlem)","ho":"hop, hey (ünlem)","err":"ee, şey (duraksama)"},"captions":[{"start":140,"end":141.3,"text":"Excuse me?"},{"start":141.8,"end":143,"text":"Excuse me, sir?"},{"start":144,"end":145.5,"text":"Excuse me?"},{"start":147,"end":149,"text":"Oh, come on."},{"start":150,"end":152,"text":"Do you have a moment, sir?"},{"start":152,"end":157.05,"text":"I'm kind of in the middle of something here."},{"start":157.05,"end":158.95,"text":"I've come a long way for you, Franck."},{"start":169,"end":171,"text":"My name is Victor."},{"start":172,"end":174,"text":"Hi."},{"start":174,"end":176,"text":"And you are...."},{"start":178,"end":179.5,"text":"You are Franck."},{"start":180.5,"end":184,"text":"You are so much more than just a sheep, aren't you?"},{"start":185,"end":188,"text":"Oh yeah? How would you know?"},{"start":190,"end":192.9,"text":"Look at you. You're an adventurer, Franck."},{"start":192.9,"end":197,"text":"Just like me, you're... a lone wolf."},{"start":198,"end":202,"text":"Tell me, does one choose to be alone?"},{"start":203,"end":205,"text":"No, one doesn't."},{"start":205,"end":207.6,"text":"One doesn’t even choose to be a wolf."},{"start":210,"end":212,"text":"Or does one?"},{"start":215,"end":218.8,"text":"Well, mister... err... Hector."},{"start":218.8,"end":220,"text":"Victor. Victor."},{"start":220,"end":226,"text":"I don’t know what you’re on about but I'm just"},{"start":226,"end":228.6,"text":"And I suggest you do the same."},{"start":228.6,"end":232,"text":"No. No no no, Franck. Wait wait wait."},{"start":232,"end":235,"text":"No. This is not... the way."},{"start":235,"end":238.5,"text":"Just give me one minute of your precious time."},{"start":238.5,"end":241.5,"text":"Precious time? Hehehe."},{"start":241.5,"end":243.5,"text":"Yeah just give me one minute."},{"start":243.5,"end":246.5,"text":"You would have one more minute, wouldn't you?"},{"start":248,"end":251,"text":"Okay half. Half a minute."},{"start":265.1,"end":269.3,"text":"I knew it."},{"start":269.3,"end":272,"text":"You will not regret this."},{"start":272,"end":275,"text":"The adventures you will have."},{"start":275,"end":278.5,"text":"All the lives you've ever wanted."},{"start":278.5,"end":281.7,"text":"All you’ve been missing."},{"start":281.7,"end":286,"text":"Here. This is... the best product we have... in store."},{"start":286,"end":290,"text":"Variable spin speed, excellent tumble performance..."},{"start":290,"end":294,"text":"...in one... handy... device. Squeaky clean."},{"start":297,"end":301,"text":"Well this... this better be good."},{"start":301,"end":304,"text":"Took me ages to tie that rope."},{"start":305,"end":307,"text":"With my fucking hooves."},{"start":307,"end":309,"text":"No more need for hooves."},{"start":309,"end":311,"text":"No more sheepy business."},{"start":312,"end":314.5,"text":"Ho! Time flies."},{"start":314.5,"end":316.7,"text":"Wait wait wait wait wait wait."},{"start":316.7,"end":318.5,"text":"How does this thing work?"},{"start":318.5,"end":321,"text":"I mean, how do I make it work?"},{"start":321,"end":322.5,"text":"No you don't."},{"start":322.5,"end":324,"text":"I just turned it on for you."},{"start":326,"end":327,"text":"When can I go?"},{"start":329,"end":330,"text":"Where can I go?"},{"start":330,"end":333,"text":"We will pick you up. Don't worry, just stay here."},{"start":333,"end":335,"text":"In this exact place."},{"start":335,"end":337,"text":"Don't move. Just wait."},{"start":338,"end":340,"text":"That's it?"},{"start":341,"end":342,"text":"Hey!"},{"start":342.5,"end":344,"text":"Hey!"},{"start":344,"end":345.5,"text":"Wait, mister!"},{"start":345.5,"end":348.9,"text":"Eh, Casper!"},{"start":348.9,"end":351,"text":"Hector whatever!"}]},{"id":"sprite-fright","type":"video","title":"Sprite Fright","creator":"Blender Foundation","year":2021,"level":"B2","category":"fun","durationSeconds":630,"genre":"horror","summaryTr":"Doğa gezisine çıkan bir öğrenci grubu, ormanın küçük sakinleriyle karşılaşır. İngiliz aksanları, hızlı grup konuşmaları ve kelime oyunları içeren bir korku komedisi.","levelNoteTr":"B2, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî bir CEFR derecesi değildir. Hızlı İngiliz İngilizcesi, argo, kısaltılmış söyleyişler ve kelime oyunları vardır. Latince tür adları ve doğa terimleri kelime desteği gerektirebilir.","advisoryTr":"Kanlı çizgi film şiddeti, ölüm, korku sahneleri, zorbalık, alkol ve ağır argo/küfür içerir. Yapımcı 13+ olarak belirtir; küçük çocuklar için uygun değildir.","videoUrl":"https://video.blender.org/object-storage/web_videos/a69d68a5-a0e0-4a80-9d66-49f093c97aaf-720.mp4","qualities":[{"label":"720p","url":"https://video.blender.org/object-storage/web_videos/a69d68a5-a0e0-4a80-9d66-49f093c97aaf-720.mp4","sizeMB":102},{"label":"1080p","url":"https://video.blender.org/object-storage/web_videos/a69d68a5-a0e0-4a80-9d66-49f093c97aaf-804.mp4","sizeMB":111}],"source":{"name":"Blender Foundation — Sprite Fright","url":"https://studio.blender.org/projects/sprite-fright/","license":"CC BY 1.0","licenseUrl":"https://creativecommons.org/licenses/by/1.0/","credit":"(CC) Blender Foundation | studio.blender.org","licenseSourceUrl":"https://studio.blender.org/projects/sprite-fright/pages/about/","watchUrl":"https://video.blender.org/videos/watch/a69d68a5-a0e0-4a80-9d66-49f093c97aaf","creditNoteTr":"Film, kapanış jeneriğiyle birlikte resmî Blender kaynağından değiştirilmeden oynatılır."},"subtitleSource":{"name":"Blender Studio — resmî İngilizce WebVTT altyazısı","url":"https://video.blender.org/object-storage/captions/541aac20-a387-4d4b-be46-fd722b33fe58-en.vtt","license":"CC BY 1.0","licenseUrl":"https://creativecommons.org/licenses/by/1.0/","changeNoteTr":"Altyazı sözleri korunmuş; biçim etiketleri kaldırılıp zamanlar saniyeye dönüştürülmüştür."},"glossary":{"cornu":"Cornu aspersum: bir kara salyangozu türü","aspersum":"Cornu aspersum: bir kara salyangozu türü","motacilla":"Motacilla flava: sarı kuyruksallayan kuşu","flava":"Motacilla flava: sarı kuyruksallayan kuşu","fungis":"mantarlar; fun guys (eğlenceli tipler) kelime oyunu","dorkwad":"aptal, ezik (aşağılayıcı argo)","innit":"öyle değil mi? (isn’t it, İngiliz argosu)","oy":"hey! (seslenme)","phil":"Phil (karakter adı)","bbq":"barbekü, mangal","piss":"işemek (kaba); piss break: tuvalet molası","shagged":"cinsel ilişkiye girmiş (kaba argo)","sprite":"orman perisi; burada yaratıkların adı/kelime oyunu","sprites":"orman perileri; filmdeki yaratıklar","psycho":"psikopat, kaçık (argo)","bitches":"sürtükler (ağır hakaret)","bastards":"alçaklar (ağır hakaret)","geezer":"herif, adam (İngiliz argosu)","weenie":"ödlek, pısırık (argo)","wagtail":"kuyruksallayan kuşu","ribbing":"takılma, alay etme","wasted":"sarhoş, kafası iyi (argo)","buns":"çörekler; Sugar Buns: tatlım (hitap)","cakes":"kekler; Sweet cakes: tatlım (hitap)","muffin":"muffin; Love muffin: sevgilim (hitap)","punks":"serseriler","aaaah":"aaa! (çığlık)","nuh":"hayır (nuh-uh: olumsuzluk ünlemi)","uh":"ee (duraksama)","mtv":"MTV (müzik televizyon kanalı)","c'mon":"haydi, hadi (come on)","dilly":"dilly-dally: oyalanmak","outta":"out of: içinden, dışarı (konuşma dili)"},"captions":[{"start":17.375,"end":19.458,"text":"Hello, Mr.Snail!"},{"start":19.458,"end":22.333,"text":"Aw, you cute little cornu aspersum."},{"start":22.333,"end":25.125,"text":"Latin name bonus-points!"},{"start":28.375,"end":30.833,"text":"Can’t believe we got stuck with the tree hugger."},{"start":30.833,"end":34.667,"text":"If I have to hear the latin name for one more animal, I swear I'm gonna kill her."},{"start":34.667,"end":39.542,"text":"Relax, Sugar Buns. While she does all the work we’ll have all the fun."},{"start":39.542,"end":42.583,"text":"Yeah! And get wasted out of our minds!"},{"start":42.583,"end":44.25,"text":"Way ahead of you, man."},{"start":44.25,"end":48.625,"text":"C’mon, team! We mustn’t dilly-dally when there’s so much nature to see!"},{"start":48.625,"end":53.667,"text":"I was thinking we should call our class project, “Fungis in a Forest!”"},{"start":53.667,"end":56.167,"text":"Get it? Because we’re a group of fun guys."},{"start":56.167,"end":57.667,"text":"And also fungis which-"},{"start":57.667,"end":62.458,"text":"Shush! That’s a yellow wagtail. And she’s in distress!"},{"start":62.75,"end":66.333,"text":"There, there, my little motacilla flava."},{"start":67.792,"end":70.042,"text":"Oh! Look at her go!"},{"start":70.375,"end":71.5,"text":"Wow!"},{"start":71.5,"end":74.417,"text":"Out of the way, dorkwad! We're camping here."},{"start":74.417,"end":77.5,"text":"Finally! Time to get that BBQ burning."},{"start":78.417,"end":80.167,"text":"Oh. Oh, dear."},{"start":87.333,"end":88.875,"text":"Gross!"},{"start":90.833,"end":95.458,"text":"Oh. Easy, guys. We’re supposed to be studying nature, not wrecking it."},{"start":95.458,"end":97.958,"text":"Piss break!"},{"start":100.708,"end":104.667,"text":"Oy, fungus freak! Make yourself useful and fix the tent."},{"start":104.667,"end":108.917,"text":"Oh, a bit of friendly campsite ribbing. Fun."},{"start":109.875,"end":112.583,"text":"She wouldn't survive 5 minutes alone in these woods."},{"start":112.583,"end":116.792,"text":"Yeah. She's a real weenie that one, innit?"},{"start":116.792,"end":119,"text":"Oy, Phil! How those sausages coming?"},{"start":119,"end":122.458,"text":"Almost ready! Just need a bit more salt..."},{"start":156.333,"end":159.208,"text":"It's incredible. It's a new species."},{"start":159.208,"end":161.875,"text":"What the bloody hell are those things?"},{"start":161.875,"end":164.542,"text":"It's like a gnome shagged a mushroom."},{"start":177.375,"end":179.583,"text":"They’re absolutely adorable."},{"start":179.583,"end":182,"text":"Yeah, absolutely bloody adorable."},{"start":182,"end":185.625,"text":"And I bet we’ll make a fortune if we catch one of those things."},{"start":185.625,"end":186.958,"text":"We'd be famous!"},{"start":186.958,"end":188.292,"text":"Get on MTV."},{"start":188.292,"end":189.875,"text":"I wonder what they taste like."},{"start":189.875,"end":192.5,"text":"We really shouldn't disrupt their habitat."},{"start":192.5,"end":195.917,"text":"Right. Sure, sure."},{"start":195.917,"end":197.5,"text":"Greetings."},{"start":197.5,"end":199,"text":"Welcome, friends."},{"start":199,"end":201.208,"text":"I'll be right down."},{"start":206.25,"end":208.75,"text":"Could I interest you in some peppermint tea?"},{"start":208.75,"end":210.667,"text":"What are you guys?"},{"start":210.667,"end":214.417,"text":"We are Sprites. We sprite balance to the forest."},{"start":214.417,"end":219.667,"text":"We take care of the animals, plants, birds, moss..."},{"start":221,"end":223.917,"text":"Guys? Guys, I..."},{"start":226.583,"end":231.542,"text":"Hey, uh, little mushroom geezer, you cool with us camping here for the night?"},{"start":231.542,"end":236.333,"text":"Absolutely. A friend of the forest is a friend of the sprites."},{"start":237.708,"end":241.375,"text":"Maybe it was just ketchup... or something... like..."},{"start":241.375,"end":249.125,"text":"Red paint? Yeah, maybe they were just painting their little hats or... something..."},{"start":255.5,"end":257.04200000000003,"text":"Guys?"},{"start":260.08299999999997,"end":261.625,"text":"Guys?"},{"start":262.41700000000003,"end":263.95799999999997,"text":"Guys, this isn't funny."},{"start":265.08299999999997,"end":266.625,"text":"Guys?"},{"start":287.20799999999997,"end":290.16700000000003,"text":"We were just gonna catch one! But they’re psycho!"},{"start":290.16700000000003,"end":292.95799999999997,"text":"You gotta get me outta these! Hurry! They’re gonna kill us!"},{"start":295.66700000000003,"end":296.58299999999997,"text":"Hurry!"},{"start":296.58299999999997,"end":299.45799999999997,"text":"Right foot, left foot, leaf and stone."},{"start":299.45799999999997,"end":303.583,"text":"You picked the wrong camping spot, bitches."},{"start":303.583,"end":305.292,"text":"Sprite them!"},{"start":305.833,"end":307.542,"text":"Run!!!"},{"start":330.25,"end":332.08299999999997,"text":"Aaaah! My eyes!"},{"start":357.625,"end":359.625,"text":"Sugar Buns?! Help me!"},{"start":367.125,"end":368.875,"text":"Sweet cakes!"},{"start":371.292,"end":373.208,"text":"Love muffin..."},{"start":374.167,"end":375.667,"text":"Huh?"},{"start":400.04200000000003,"end":403.45799999999997,"text":"No, no, no! I can’t swim!"},{"start":415.08299999999997,"end":416.875,"text":"Yes!"},{"start":418.29200000000003,"end":419.70799999999997,"text":"No!"},{"start":432.833,"end":436.20799999999997,"text":"I don’t want to hurt you! Just keep your distance!"},{"start":437.20799999999997,"end":441.125,"text":"All right, then. Eat salt, you little green bastards!"},{"start":476.83299999999997,"end":478.54200000000003,"text":"Nuh-uh-uh."},{"start":478.54200000000003,"end":483.333,"text":"Those punks treated the world as their own personal rubbish bin."},{"start":483.333,"end":485.625,"text":"And you set them free!"},{"start":485.625,"end":487.833,"text":"Now you'll join them!"},{"start":525.875,"end":529.167,"text":"I’ll give you that one, Brother Bird!"},{"start":530,"end":535.417,"text":"Alright sprites, let’s burn the bodies and have some peppermint tea."}]}];
